public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums.length == 0) {
        return permutations;
    }

    recursivePermute(nums, 0, new ArrayList<>(), permutations);
    return permutations;
}

private void recursivePermute(int[] nums, int start, List<Integer> current, List<List<Integer>> permutations) {
    if (start == nums.length) {
        permutations.add(new ArrayList<>(current));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        current.add(nums[i]);
        recursivePermute(nums, i + 1, current, permutations);
        current.remove(current.size() - 1);
    }
}

static List<List<Integer>> permute(int[] nums) {
