    _permute(nums, 0, result);
    return result;
}

static void _permute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(Arrays.asList(nums));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        _permute(nums, start + 1, result);
        swap(nums, start, i);
    }
}

static void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

