public static int maxRegions(int N) {
    // Calculate the maximum number of regions that can be created by dividing the plane into N-2 triangles
    // The number of regions is equal to the number of possible ways to choose the region that any of the N triangles can belong to
    // This can be calculated as C(N-1, 2) where C(n, k) is the binomial coefficient
    // The naive algorithm would be to calculate this value recursively or use a combination of loops, but this is very inefficient
    // Instead, we will use a closed-form expression for the binomial coefficient using the formula:
    // C(n, k) = (n choose k) = n! / (k! * (n - k)!)
    // This formula allows us to calculate the binomial coefficient using integer division, which is much faster than doing it recursively or using loops
    int regions = N * (N - 1) / 2;
    return regions;
}

