public static int maxRegions(int N) {
    // Find the maximum number of regions that can be formed by dividing the plane into N triangles
    // The algorithm used is based on the following observation:
    // Each triangle can be aligned in two ways: directly and indirectly
    // Directly aligned triangles form a region, while indirectly aligned triangles do not
    // Therefore, the number of regions is equal to the number of directly aligned triangles

    // Initialize the number of directly aligned triangles as 1
    int directlyAlignedTriangles = 1;

    // Loop until there are no more triangles left
    while (N > 0) {
        // If there are no directly aligned triangles, add 1 directly aligned triangle
        if (directlyAlignedTriangles == 0) {
            directlyAlignedTriangles = 1;
        }

        // Find the number of indirectly aligned triangles
        int indirectlyAlignedTriangles = N - directlyAlignedTriangles;

        // Find the maximum number of regions that can be formed with the current number of triangles
        int maxRegions = Math.max(directlyAlignedTriangles, indirectlyAlignedTriangles);

        // Return the maximum number of regions
        return maxRegions;
    }
}

