public double trimMean(int[] arr) {
  // Sort the array in ascending order
  Arrays.sort(arr);

  // Calculate the 5% of smallest numbers to remove
  int numToRemove = (int) (arr.length * 0.05);
  int[] smallNumbers = Arrays.copyOfRange(arr, 0, numToRemove);

  // Calculate the 5% of largest numbers to remove
  numToRemove = (int) (arr.length * 0.05);
  int[] largeNumbers = Arrays.copyOfRange(arr, arr.length - numToRemove, arr.length);

  // Calculate the mean of the remaining numbers
  double mean = 0;
  for (int i = numToRemove; i < arr.length - numToRemove; i++) {
    mean += arr[i];
  }
  mean /= (arr.length - 2 * numToRemove);

  // Return the mean with an error within 10^-5
  return roundTo5Decimals(mean);
}

private double roundTo5Decimals(double number) {
  return (double) Math.round(number * 100000) / 100000;
}

public double trimMean(int[] arr) {
    // Sort the array in descending order
    Arrays.sort(arr);

    // Calculate the number of elements to remove from the beginning and end
    int numToRemoveFromStart = (int)Math.ceil(arr.length * 0.05);
    int numToRemoveFromEnd = (int)Math.floor(arr.length * 0.05);

    // Remove elements from the beginning and end of the array
    int[] trimmedArr = Arrays.copyOfRange(arr, numToRemoveFromStart, arr.length - numToRemoveFromEnd);

    // Calculate the mean of the remaining elements
    double mean = Arrays.stream(trimmedArr).mapToDouble(i -> (double)i).average().orElse(0.0);

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
}

