  int largest = (int)Math.ceil(arr.length * 0.05);

  // Remove the smallest 5% and largest 5% of the elements
  double sum = 0;
  for (int i = smallest; i < arr.length - largest; i++) {
    sum += arr[i];
  }

  // Calculate the mean with an error within 10^-5
