    int[] sorted = arr.clone();
    Arrays.sort(sorted);
    int n = sorted.length;
    int index5p = (int) (n * 0.05);
    int index95p = n - (int) (n * 0.05);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = index5p; i < n - index95p; i++) {
        sum += sorted[i];
    }

    // Calculate the mean
    return (double) sum / (n - 2 * index5p);
}

public boolean canArrange(int[] arr, int k) {
  int n = arr.length;
  int sum = 0;
  for (int i = 0; i < n; i++) {
    sum += arr[i];
  }
  if (sum % k != 0) {
    return false;
  }
  int pairs = n / 2;
  int pairSum = sum / pairs;
  for (int i = 0; i < n; i++) {
    int j = i + pairs;
    if (j < n) {
      if (arr[i] + arr[j] != pairSum) {
        return false;
      }
    }
  }
  return true;
}

public static boolean canArrange(int[] arr, int k) {
int n = arr.length;
if (n % 2 != 0 || k <= 1) {
return false;
}

// Sort the array in ascending order
Arrays.sort(arr);

// Iterate over the pairs
for (int i = 0; i < n - 1; i += 2) {
// Check if the sum of the current pair is divisible by k
if (arr[i] % k == 0 && (arr[i + 1] - arr[i]) % k == 0) {
return true;
}
}

return false;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }

    if (sum % k != 0) {
        return false;
    }

    int pairs = n / 2;
    int pairSum = sum / pairs;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if ((arr[i] + arr[j]) % pairSum == 0) {
                pairs--;
                if (pairs == 0) {
                    return true;
                }
            }
        }
    }

    return false;
}

