    if (n % 2 == 1) {
        return false;
    }
    if (k == 1) {
        return true;
    }
    for (int i = 0; i < n; i += 2) {
        if (arr[i] % k != 0) {
            continue;
        }
        int sum = arr[i];
        for (int j = i + 1; j < n; j += 2) {
            sum += arr[j];
            if (sum % k == 0) {
                return true;
            }
        }
    }
    return false;
}

static boolean canArrange(int[] arr, int k) {
        // count the frequency of each element in the array
        int[] freq = new int[10001];
        for (int num : arr) {
            freq[num]++;
        }

        // create a map to store the pairs
        Map<Integer, Integer> pairs = new HashMap<>();

        // loop through the array and check if there are any pairs that can be formed
        for (int num : arr) {
            if (pairs.containsKey(num)) {
                continue;
            }

            // check if there is a pair that can be formed by adding num to itself
            int pair = num + num;
            if (pairs.containsKey(pair)) {
                return true;
            }

            // check if there is a pair that can be formed by subtracting num from itself
            pair = num - num;
            if (pairs.containsKey(pair)) {
                return true;
            }

            // check if there is a pair that can be formed by adding num to any other number
            for (int i = 1; i < k; i++) {
                int pair1 = num + i;
                int pair2 = i + num;
                if (pairs.containsKey(pair1) || pairs.containsKey(pair2)) {
                    return true;
                }
            }
        }

