    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize a queue to store the starting node and its distance from the starting node
  Queue<int[]> queue = new LinkedList<>();
  queue.offer(new int[]{0, 0});

  // Initialize a boolean array to mark the visited nodes
  boolean[] visited = new boolean[n];

  // Initialize a map to store the minimum time required to collect all the apples and return to node 0
  Map<Integer, Integer> time = new HashMap<>();
  time.put(0, 0);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Get the current node and its distance from the starting node
    int[] current = queue.poll();
    int node = current[0];
    int dist = current[1];

    // If the current node has an apple and has not been visited before, mark it as visited and update the minimum time required to collect all the apples and return to node 0
    if (hasApple[node] && !visited[node]) {
      visited[node] = true;
      time.put(node, dist);
    }

    // Loop through the neighbors of the current node
    for (int[] neighbor : edges[node]) {
      // If the neighbor has not been visited before, mark it as visited, update the minimum time required to collect all the apples and return to node 0, and add it to the queue
      if (!visited[neighbor[0]]) {
        visited[neighbor[0]] = true;
        time.put(neighbor[0], Math.min(dist + 1, time.getOrDefault(neighbor[0], Integer.MAX_VALUE)));
        queue.offer(new int[]{neighbor[0], dist + 1});
      }
    }
  }

  // Loop through the nodes and update the minimum time required to collect all the apples and return to node 0 if a shorter path is found
  for (int i = 0; i < n; i++) {
    if (hasApple[i] && !visited[i]) {
      time.put(i, Math.min(time.getOrDefault(i, Integer.MAX_VALUE), time.getOrDefault(0, 0) + 1));
    }
  }

  // Return the minimum time required to collect all the apples and return to node 0
  return time.getOrDefault(0, Integer.MAX_VALUE);
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[]{0, 0});
    int time = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            int[] tuple = queue.poll();
            int node = tuple[0];
            int apple = tuple[1];
            if (node == n - 1) {
                return time;
            }
            for (int[] edge : edges) {
                int neighbor = edge[0] == node ? edge[1] : edge[0];
                if (!hasApple[neighbor]) {
                    queue.offer(new int[]{neighbor, apple});
                }
            }
        }
        time++;
    }
    return -1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize a queue to store the nodes to be visited
  Queue<Integer> queue = new LinkedList<>();

  // Initialize a set to keep track of the visited nodes
  Set<Integer> visited = new HashSet<>();

  // Initialize a map to store the time taken to visit each node
  Map<Integer, Integer> timeTaken = new HashMap<>();

  // Initialize a variable to store the minimum time required
  int minTime = 0;

  // Add node 0 to the queue and mark it as visited
  queue.add(0);
  visited.add(0);
  timeTaken.put(0, 0);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Get the node at the front of the queue
    int node = queue.poll();

    // If the node has an apple, add it to the list of apples collected
    if (hasApple[node]) {
      // Increment the minimum time required
      minTime++;
    }

    // Get all the neighbors of the node
    for (int neighbor : edges[node]) {
      // If the neighbor has not been visited, mark it as visited and add it to the queue
      if (!visited.contains(neighbor)) {
        queue.add(neighbor);
        visited.add(neighbor);
        timeTaken.put(neighbor, timeTaken.get(node) + 1);
      }
    }
  }

  // Return the minimum time required
  return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Mark the nodes that have apples
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            graph.mark(i);
        }
    }

    // Initialize a priority queue for the nodes
    PriorityQueue<Node> queue = new PriorityQueue<>(new NodeComparator());
    for (int i = 0; i < n; i++) {
        if (graph.isMarked(i)) {
            queue.offer(new Node(i, 0));
        }
    }

    // BFS to collect apples and find the minimum time
    int time = 0;
    while (!queue.isEmpty()) {
        Node node = queue.poll();
        time++;
        for (int neighbor : graph.adjacentTo(node.id)) {
            if (!graph.isVisited(neighbor)) {
                queue.offer(new Node(neighbor, node.time + 1));
            }
            if (graph.isMarked(neighbor)) {
                graph.unmark(neighbor);
            }
        }
    }
    return time;
}

