    // Return the minimum distance to collect all the apples and return to node 0
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime = Math.max(minTime, dist[i]);
        }
    }
    return minTime;
}

public String sortString(String s) {
    char[] array = s.toCharArray();
    Arrays.sort(array);
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < array.length; i++) {
        while (array[i] == result.charAt(result.length() - 1)) {
            i++;
        }
        result.append(array[i]);
    }
    for (int i = array.length - 1; i >= 0; i--) {
        while (array[i] == result.charAt(result.length() - 1)) {
            i--;
        }
        result.append(array[i]);
    }
    return result.toString();
}

public String sortString(String s) {
    StringBuilder sb = new StringBuilder();
    while (s.length() > 0) {
        char min = s.charAt(0);
        char max = s.charAt(0);
        for (char c : s.toCharArray()) {
            if (c < min) {
                min = c;
            } else if (c > max) {
                max = c;
            }
        }
        sb.append(min);
        sb.append(max);
        s = s.replace(min, ' ').replace(max, ' ');
    }
    return sb.toString();
}

