public static boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    int avg = sum / 2;

    int leftSum = 0;
    int rightSum = 0;

    for (int i = 0; i < nums.length; i++) {
        if (leftSum > avg) {
            return false;
        }

        if (leftSum + nums[i] > avg) {
            rightSum += avg - leftSum;
            break;
        }

        leftSum += nums[i];
    }

    for (int i = nums.length - 1; i >= 0; i--) {
        if (rightSum > avg) {
            return false;
        }

        if (rightSum + nums[i] > avg) {
            leftSum += avg - rightSum;
            break;
        }

        rightSum += nums[i];
    }

    return leftSum == avg && rightSum == avg;
}

