public boolean hasAllCodes(String s, int k) {
    Set<String> substringSet = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        substringSet.add(s.substring(i, i + k));
    }
    Set<String> binaryStringSet = new HashSet<>();
    for (int i = 0; i < k; i++) {
        binaryStringSet.add("0");
        binaryStringSet.add("1");
    }
    return binaryStringSet.containsAll(substringSet);
}

