public int minOperations(int n) {
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }

  int minOps = 0;
  int currentSum = 0;
  for (int i = 0; i < n; i++) {
    currentSum += arr[i];
    if (currentSum == n) {
      return minOps;
    }
    minOps++;
  }

  int targetSum = currentSum / 2;
  int currentDiff = targetSum - currentSum;

