  int minOperations = 0, currentSum = 0;

  // Loop through the array, starting from the second element
  for (int i = 1; i < n; i++) {
    // Increment the minimum number of operations if the current sum is not equal to the sum of the first element and the current element
    if (currentSum != (i * 2) + 1) {
