public int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return k;
    }

    int[] fib = new int[] {1, 1};
    for (int i = 2; i < k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    int minNum = k;
    for (int i = 0; i < k; i++) {
        int currSum = 0;
        for (int j = i; j < k; j++) {
            currSum += fib[j];
            if (currSum == k) {
                minNum = Math.min(minNum, j - i + 1);
                break;
            } else if (currSum > k) {
                break;
            }
        }
    }

    return minNum;
}

public int findMinFibonacciNumbers(int k) {
  int[] fib = new int[] {1, 1};
  int n = 2;
  while (fib[n - 1] + fib[n - 2] <= k) {
    fib[n++] = fib[n - 1] + fib[n - 2];
  }
  return n - 1;
}

int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return 1;
    }

    // Initialize F_i and F_{i+1}
    int F_i = 1;
    int F_i_plus_1 = 1;

    // Initialize result
    int result = 0;

    while (F_i_plus_1 < k) {
        // Calculate F_{i+2}
        int F_i_plus_2 = F_i + F_i_plus_1;

        // Check if F_{i+2} is less than k
        if (F_i_plus_2 < k) {
            // Update F_i and F_{i+1}
            F_i = F_i_plus_1;
            F_i_plus_1 = F_i_plus_2;
        } else {
            // Break if F_{i+2} is greater than k
            break;
        }

        // Increment result
        result++;
    }

    return result + 1;
