      if (uniqueSubstrings.contains(substring.toString())) {
        continue;
      }
      // Add the substring to the set of unique substrings
      uniqueSubstrings.add(substring.toString());
      // Update the max counter if the number of unique substrings is greater than the current max
      if (uniqueSubstrings.size() > maxUniqueSubstrings) {
        maxUniqueSubstrings = uniqueSubstrings.size();
      }
    }
  }
  // Return the maximum number of unique substrings
  return maxUniqueSubstrings;
}

