public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();

    // Using a priority queue to keep track of the numbers to be processed
    PriorityQueue<Integer> queue = new PriorityQueue<>();

    // Initializing the queue with the first number in the range
    queue.offer(low);

    // Looping until the queue is empty
    while (!queue.isEmpty()) {
        // Retrieving the top number from the queue
        int num = queue.poll();

        // If the number falls within the range, add it to the list of stepping numbers
        if (num >= low && num <= high) {
            steppingNumbers.add(num);
        }

        // Checking if the number can be incremented
        int lastDigit = num % 10;
        int adjDigit = lastDigit == 9 ? 0 : lastDigit + 1;
        int incNum = num / 10 * 10 + adjDigit;
        if (incNum <= high) {
            queue.offer(incNum);
        }

        // Checking if the number can be decremented
        lastDigit = num % 10;
        adjDigit = lastDigit == 0 ? 9 : lastDigit - 1;
        int decNum = num / 10 * 10 + adjDigit;
        if (decNum >= low) {
            queue.offer(decNum);
        }
    }

    return steppingNumbers;
}

