public static int squarePermutations(int[] A) {
    int N = A.length;
    int[][] dp = new int[N][N];

    for (int i = 0; i < N; i++) {
        dp[i][i] = 1;
    }

    for (int i = 1; i < N; i++) {
        for (int j = 0; j < N - i; j++) {
            int k = j + i;
            if (A[j] + A[k] == dp[j + 1][k]) {
                dp[j][k] = 2 * dp[j + 1][k];
            } else if (A[j] + A[k] == dp[j + 1][k - 1]) {
                dp[j][k] = 2 * dp[j + 1][k - 1];
            } else {
                dp[j][k] = dp[j + 1][k] + dp[j + 1][k - 1];
            }
        }
    }

    return dp[0][N - 1];
}

