            for (int i = 0; i + len - 1 < A.length; i++) {
                int j = i + len - 1;
                if (A[i] + A[j] == len * len) {
                    dp[i][j] = dp[i + 1][j - 1] + dp[i + 1][j];
                } else {
                    dp[i][j] = dp[i + 1][j - 1];
                }
            }
        }
        int[] count = new int[A.length];
