static int squarePermutations(int[] A) {
    int N = A.length;
    int[][] dp = new int[N][N];
    for (int i = 0; i < N; i++) {
        dp[i][i] = 1;
    }
    for (int L = 2; L <= N; L++) {
        for (int i = 0; i < N - L + 1; i++) {
            int j = i + L - 1;
            for (int k = i; k < j; k++) {
                dp[i][j] += dp[k + 1][j] * dp[i][k];
            }
        }
    }
    return dp[0][N - 1];
}

