    // Sort the digits of n in ascending order
    int[] digits = new int[10];
    for (int i = 0; i < digits.length; i++) {
        digits[i] = (n % 10) + 1;
        n /= 10;
    }
    Arrays.sort(digits);

    // Check if the rearranged digits form a valid integer
    int newNumber = 0;
    for (int i = digits.length - 1; i >= 0; i--) {
        newNumber = newNumber * 10 + digits[i];
    }
