        return -1;
    }
}

public static int findSmallestInteger(int n) {
    // Step 1: Get the digits of n
    int[] digits = new int[10];
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    // Step 2: Find the first digit that is not in its place
    int firstOutOfPlaceDigit = 0;
    for (int i = 1; i <= 9; i++) {
        if (digits[i] > 1) {
            firstOutOfPlaceDigit = i;
            break;
        }
    }

    // Step 3: If no digit is not in its place, return -1
    if (firstOutOfPlaceDigit == 0) {
        return -1;
    }

    // Step 4: Rearrange the digits
    int rearrangedDigits = 0;
    for (int i = 0; i < 10; i++) {
        if (i != firstOutOfPlaceDigit) {
            rearrangedDigits = rearrangedDigits * 10 + digits[i];
        }
    }
    rearrangedDigits = rearrangedDigits * 10 + firstOutOfPlaceDigit;

    return rearrangedDigits;
}

