    }
    int max = 0;
    int current = 0;
    char c = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c2 = s.charAt(i);
        if (c == c2) {
            current++;
        } else {
            max = Math.max(max, current);
            current = 0;
            c = c2;
        }
    }
    return Math.max(max, current);
}

public static int calculateEnergy(String s) {
    int energy = 0;
    for (int i = 0; i < s.length(); i++) {
      int j = i + 1;
      while (j < s.length() && s.charAt(j) == s.charAt(j - 1)) {
        j++;
      }
      energy = Math.max(energy, j - i);
      i = j;
    }
    return energy;
  }

