public static int minPerfectSquareSum(int n) {
    int count = 0;

    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            count++;
            if (n / i != i) {
                count++;
            }
        }
    }

    return count;
}

public static int minPerfectSquareSum(int n) {
    // Find the minimum number of perfect square numbers that sum up to n
    int minSquares = 0;
    for (int i = 1; i <= n; i++) {
        int square = (int) Math.sqrt(i);
        if (square * square == i) {
            minSquares++;
        }
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        return -1;
    }
    int minSquares = 0;
    int currentSum = 0;
    for (int i = 1; i <= n; i++) {
        if (i * i > n) {
            break;
        }
        currentSum += i * i;
        minSquares++;
    }
    if (currentSum == n) {
        return minSquares;
    }
    return minSquares - 1;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    int squareSum = 0;
    for (int i = 1; i <= n; i++) {
        squareSum += i * i;
        if (squareSum > n) {
            minSquares++;
            squareSum = i * i;
        }
    }
    return minSquares;
}

