    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            count++;
        }
    }
    return count;
}

private static String reverseWords(String s) {

        String result = "";
        for(String word : s.split(" ")) {
            char[] letters = word.toCharArray();
            for(int i = 0; i < letters.length; i++) {
                letters[i] = reverseChar(letters[i]);
            }
            result += String.join("", Arrays.asList(letters)) + "";
        }
        return result;
    }

private static char reverseChar(char letter){
        switch(letter) {
            case 'a':
                return 'A';
            case 'b':
                return 'B';
            // ...
            case 'z':
                return 'Z';
            default:
                return Character.toLowerCase(letter);
        }
    }

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        reversedSentence.append(reversedWord.toString());
        reversedSentence.append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().replaceAll("( )+", " ").trim();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();

    // Skip leading spaces and get the first word
    int firstSpace = s.indexOf(' ');
    int firstWord = firstSpace > 0 ? firstSpace + 1 : 0;

    while (firstWord < s.length()) {
        // Find the next space
        int nextSpace = s.indexOf(' ', firstWord);
        int wordLength = nextSpace > 0 ? nextSpace - firstWord : s.length() - firstWord;

        // Reverse the word
        for (int i = wordLength - 1; i >= 0; i--) {
            result.append(s.charAt(firstWord + i));
        }

        // Add a space if there are more words
        if (nextSpace > 0) {
            result.append(' ');
        }

        // Get the next word
        firstWord = nextSpace > 0 ? nextSpace + 1 : s.length();
    }

    return result.toString();
}

